"""Project table builder with frozen environment-layer contact materials."""

from mani_skill.utils.scene_builder.table import (
    TableSceneBuilder as ManiSkillTableSceneBuilder,
)

from tasks.config.contact_materials import apply_table_contact_material


class TableSceneBuilder(ManiSkillTableSceneBuilder):
    """Drop-in builder that explicitly freezes table and ground at 0.30/0.30.

    Tasks should import this class instead of ManiSkill's builder. The material
    is assigned inside ``build`` so task authors cannot forget a second call.
    """

    def build(self):
        result = super().build()
        shape_count = apply_table_contact_material(self)
        if shape_count < 2:
            raise RuntimeError(
                "Frozen TableSceneBuilder expected collidable table and ground"
            )
        self.frozen_contact_shape_count = shape_count
        return result
